import { useMemo, useState } from 'react'
import { Activity, AlertTriangle, ArrowDownRight, CheckCircle2, GitCompare, ShieldAlert } from 'lucide-react'

export type PosturePoint = { label: string; risk: number; blastRadius: number; critical: number; verified: number }

export function SecurityPostureEvolution({ points, baselineLabel = 'Baseline', onSelect, assuranceConflicts = 0, assuranceConfidence = 0 }: { points: PosturePoint[]; baselineLabel?: string; onSelect?: (point: PosturePoint) => void; assuranceConflicts?: number; assuranceConfidence?: number }) {
  const [selectedIndex, setSelectedIndex] = useState(Math.max(0, points.length - 1))
  const selected = points[selectedIndex]
  const first = points[0]
  const delta = selected && first ? selected.risk - first.risk : 0
  const maxRisk = Math.max(100, ...points.map((p) => p.risk))
  const chartW = 860, chartH = 240, padX = 28, padY = 24
  const x = (i: number) => padX + (points.length <= 1 ? 0 : i * ((chartW - padX * 2) / (points.length - 1)))
  const y = (value: number) => chartH - padY - (value / maxRisk) * (chartH - padY * 2)
  const riskPath = points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${x(i)} ${y(p.risk)}`).join(' ')
  const areaPath = `${riskPath} L ${x(points.length - 1)} ${chartH - padY} L ${x(0)} ${chartH - padY} Z`
  const milestones = useMemo(() => points.filter((p) => p.verified > 0).map((p) => p.label), [points])
  if (!selected) return null
  return <section className="overflow-hidden rounded-2xl border bg-card"><header className="flex flex-wrap items-center justify-between gap-3 border-b px-5 py-4"><div><div className="flex items-center gap-2 font-semibold"><Activity className="h-4 w-4 text-primary" /> Security Posture Evolution</div><p className="mt-1 text-xs text-muted-foreground">Track measurable security change across detection, remediation, re-validation, and assurance confidence.</p></div><div className="flex flex-wrap gap-2"><span className="rounded-full border px-2.5 py-1 text-[10px] font-semibold">{milestones.length} verification milestones</span><span className="rounded-full border px-2.5 py-1 text-[10px] font-semibold">{Math.round(assuranceConfidence)}% confidence</span>{assuranceConflicts > 0 && <span className="inline-flex items-center gap-1 rounded-full border border-amber-500/30 bg-amber-500/5 px-2.5 py-1 text-[10px] font-semibold text-amber-600"><AlertTriangle className="h-3 w-3" /> {assuranceConflicts} conflicts</span>}</div></header><div className="grid gap-5 p-5 lg:grid-cols-[minmax(0,1fr)_280px]"><div className="overflow-auto rounded-xl border bg-muted/10 p-3"><svg viewBox={`0 0 ${chartW} ${chartH}`} className="min-w-[720px]" role="img" aria-label="Security posture risk evolution"><defs><linearGradient id="posture-area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="currentColor" stopOpacity=".20" /><stop offset="100%" stopColor="currentColor" stopOpacity="0" /></linearGradient></defs>{[0,25,50,75,100].map((tick) => <g key={tick}><line x1={padX} x2={chartW - padX} y1={y(tick)} y2={y(tick)} stroke="currentColor" className="text-border/70" strokeWidth="1" /><text x={6} y={y(tick) + 3} className="fill-current text-[9px] text-muted-foreground">{tick}</text></g>)}<path d={areaPath} fill="url(#posture-area)" className="text-primary" /><path d={riskPath} fill="none" stroke="currentColor" strokeWidth="3" className="text-primary" />{points.map((point, i) => { const active = i === selectedIndex; return <g key={`${point.label}-${i}`} onClick={() => { setSelectedIndex(i); onSelect?.(point) }} className="cursor-pointer"><circle cx={x(i)} cy={y(point.risk)} r={active ? 6 : 4} fill="currentColor" className={active ? 'text-primary' : 'text-muted-foreground'} /><text x={x(i)} y={chartH - 5} textAnchor="middle" className="fill-current text-[9px] text-muted-foreground">{point.label}</text></g> })}</svg></div><aside className="rounded-2xl border bg-muted/10 p-5"><div className="text-[10px] font-semibold uppercase tracking-[0.14em] text-muted-foreground">Selected checkpoint</div><div className="mt-2 text-lg font-bold">{selected.label}</div><div className="mt-5 grid grid-cols-2 gap-2"><Mini icon={<ShieldAlert className="h-3.5 w-3.5" />} label="Risk" value={selected.risk} /><Mini icon={<GitCompare className="h-3.5 w-3.5" />} label="Blast" value={selected.blastRadius} /><Mini icon={<ShieldAlert className="h-3.5 w-3.5" />} label="Critical" value={selected.critical} /><Mini icon={<CheckCircle2 className="h-3.5 w-3.5" />} label="Verified" value={selected.verified} /></div><div className="mt-5 rounded-xl border bg-background p-3"><div className="text-[9px] uppercase tracking-wider text-muted-foreground">Change from {baselineLabel}</div><div className="mt-1 flex items-center gap-2 text-2xl font-black">{delta <= 0 ? <ArrowDownRight className="h-5 w-5 text-emerald-600" /> : <ArrowDownRight className="h-5 w-5 rotate-90 text-destructive" />} {delta > 0 ? '+' : ''}{delta}</div><div className="text-[10px] text-muted-foreground">risk points</div></div>{assuranceConflicts > 0 && <div className="mt-4 rounded-xl border border-amber-500/20 bg-amber-500/5 p-3 text-[10px] leading-4 text-amber-700"><div className="font-semibold">Assurance caveat</div><div className="mt-1">{assuranceConflicts} cross-source conflict(s) reduce certainty in this posture signal.</div></div>}</aside></div></section>
}
function Mini({ icon, label, value }: { icon: React.ReactNode; label: string; value: number }) { return <div className="rounded-lg border bg-background px-3 py-2"><div className="flex items-center gap-1 text-[9px] text-muted-foreground">{icon}{label}</div><div className="mt-1 text-lg font-bold">{value}</div></div> }
